/* G3 Sec 2 generators, part B: Ch7 Congruence and Similarity, Ch8 Pythagoras, Ch9 Trigonometric Ratios (2 gyms),
   Ch10 Pyramids, Cones and Spheres (3 gyms), Ch11 Statistical Diagrams, Ch12 Central Tendency, Ch13 Probability. */
'use strict';
module.exports = function(H){
  const {blank, gcd, sp} = H, B = blank;
  const PI = Math.PI, rd = (x, d) => +x.toFixed(d), g = [];
  const D = Math.PI / 180, sinD = a => Math.sin(a * D), cosD = a => Math.cos(a * D), tanD = a => Math.tan(a * D);
  const asinD = x => Math.asin(x) / D, acosD = x => Math.acos(x) / D, atanD = x => Math.atan(x) / D;
  const TRIPLES = [[3, 4, 5], [5, 12, 13], [8, 15, 17], [7, 24, 25]];
  const tri = r => { const t = r.pick(TRIPLES), k = r.int(1, t[2] > 17 ? 1 : (t[2] > 5 ? 2 : 4)); return t.map(v => v * k); };   // small right-angled triples, hypotenuse at most ~34

  /* ---- Congruence and similarity ---- */
  g.push({id: 'G3.2.congruence-and-similarity.1', plain: [
    r => { const k = r.pick([2, 3, 4]), a = r.int(3, 9), b = r.int(4, 10), c = r.int(5, 12); return B(`Triangles $ABC$ and $PQR$ are similar with $AB = ${a}$ cm, $BC = ${b}$ cm, $PQ = ${a * k}$ cm. Find $QR$ in cm.`, b * k, `Scale factor = ${a * k} ÷ ${a} = ${k}, so $QR = ${b} \\times ${k} = ${b * k}$ cm.`); },
    r => { const a = r.int(4, 9), k = r.pick([1.5, 2, 2.5, 3]); return B(`Two similar figures have corresponding sides ${a} cm and ${rd(a * k, 1)} cm. Find the scale factor from the smaller to the larger figure.`, k, `${rd(a * k, 1)} ÷ ${a} = ${k}.`); },
    r => { const a = r.int(2, 4), b = a + r.int(1, 3), A = r.int(5, 20); if (gcd(a, b) !== 1) return null; return B(`Two similar figures have corresponding lengths in the ratio ${a} : ${b}. The area of the smaller figure is ${A * a * a} cm². Find the area of the larger figure in cm².`, A * b * b, `Area ratio = ${a * a} : ${b * b}. Area = ${A * a * a} ÷ ${a * a} × ${b * b} = ${A * b * b} cm².`); },
    r => { const a = r.int(2, 3), b = a + r.int(1, 2), V = r.int(2, 9); if (gcd(a, b) !== 1) return null; return B(`Two similar solids have corresponding lengths in the ratio ${a} : ${b}. The volume of the smaller solid is ${V * a ** 3} cm³. Find the volume of the larger solid in cm³.`, V * b ** 3, `Volume ratio = ${a ** 3} : ${b ** 3}. Volume = ${V * a ** 3} ÷ ${a ** 3} × ${b ** 3} = ${V * b ** 3} cm³.`); },
    r => { const a = r.int(2, 5), b = a + r.int(1, 4), A = r.int(3, 12); if (gcd(a, b) !== 1) return null; return B(`Two similar figures have areas ${A * a * a} cm² and ${A * b * b} cm². The shorter side of the smaller figure is ${a * 2} cm. Find the corresponding side of the larger figure in cm.`, b * 2, `Length ratio = $\\sqrt{${A * a * a}} : \\sqrt{${A * b * b}}$ = ${a} : ${b}. Side = ${a * 2} × ${b} ÷ ${a} = ${b * 2} cm.`); },
    r => { const a = r.int(2, 4), b = a + r.int(1, 3); if (gcd(a, b) !== 1) return null; return B(`Two similar cylinders have volumes ${a ** 3 * 8} cm³ and ${b ** 3 * 8} cm³. The height of the smaller cylinder is ${a * 3} cm. Find the height of the larger cylinder in cm.`, b * 3, `Volume ratio ${a ** 3} : ${b ** 3} gives length ratio ${a} : ${b}. Height = ${a * 3} ÷ ${a} × ${b} = ${b * 3} cm.`); },
    r => { const a = r.int(3, 8), b = r.int(2, 6), c = r.int(2, 4); return B(`In triangle $ABC$, $DE \\parallel BC$ with $D$ on $AB$ and $E$ on $AC$. $AD = ${a}$ cm, $DB = ${b}$ cm and $BC = ${(a + b) * c}$ cm. Find $DE$ in cm.`, a * c, `$\\dfrac{DE}{BC} = \\dfrac{AD}{AB} = \\dfrac{${a}}{${a + b}}$, so $DE = ${(a + b) * c} \\times \\dfrac{${a}}{${a + b}} = ${a * c}$ cm.`); },
    r => { const k = r.int(2, 6); return B(`The lengths of two similar figures are in the ratio 1 : ${k}. Find the ratio of their areas in the form 1 : $n$. Give $n$.`, k * k, `The area ratio is $1^2 : ${k}^2 = 1 : ${k * k}$.`); },
    r => { const k = r.int(2, 5); return B(`The lengths of two similar solids are in the ratio 1 : ${k}. Find the ratio of their volumes in the form 1 : $n$. Give $n$.`, k ** 3, `The volume ratio is $1 : ${k}^3 = 1 : ${k ** 3}$.`); },
    r => { const s = r.int(2, 6), t = r.int(2, 5); return B(`A rectangle measures ${s} cm by ${s * 2} cm. A similar rectangle has a shorter side of ${s * t} cm. Find the longer side of the similar rectangle in cm.`, 2 * s * t, `Scale factor ${t}, so the longer side is ${s * 2} × ${t} = ${2 * s * t} cm.`); },
    r => { const a = r.int(3, 6), b = r.int(4, 8); return B(`Triangles $ABC$ and $DEF$ are congruent with $AB = DE$, $BC = EF$ and $\\angle B = \\angle E$. If $AB = ${a}$ cm and $\\angle B = ${b * 10}°$, find $\\angle E$ in degrees.`, b * 10, 'Congruent triangles have equal corresponding angles.'); },
    r => { const k = r.int(2, 4), L = r.int(5, 12); return B(`A model of a building is made to a scale of 1 : ${k * 50}. The model is ${L} cm tall. Find the height of the real building in metres.`, L * k * 50 / 100, `Real height = ${L} × ${k * 50} cm = ${L * k * 50} cm = ${L * k * 50 / 100} m.`); },
    r => { const k = r.int(2, 5), A = r.int(2, 9); return B(`On a map, 1 cm represents ${k} km. A lake has an area of ${A} cm² on the map. Find its actual area in km².`, A * k * k, `Area scale = ${k}² = ${k * k}, so the area is ${A} × ${k * k} = ${A * k * k} km².`); },
    r => { const a = r.int(2, 4), b = a + 1, h = r.int(2, 5); return B(`Two similar cones have heights in the ratio ${a} : ${b}. The smaller cone has a base area of ${a * a * h} cm². Find the base area of the larger cone in cm².`, b * b * h, `Base areas are in the ratio ${a * a} : ${b * b}, so the larger base area is ${a * a * h} ÷ ${a * a} × ${b * b} = ${b * b * h} cm².`); },
    r => { const a = r.int(3, 8), k = r.int(2, 5); return B(`Triangle $ABC$ has $AB = ${a}$ cm. Triangle $A'B'C'$ is an enlargement of $ABC$ with scale factor ${k}. Find $A'B'$ in cm.`, a * k, `${a} × ${k} = ${a * k} cm.`); }
  ], word: [
    r => { const h = r.int(15, 20) / 10, s = r.int(2, 4), S = s * r.int(4, 9); return B(`A man ${h} m tall casts a shadow ${s} m long. At the same time a tree casts a shadow ${S} m long. Find the height of the tree in metres.`, rd(h * S / s, 2), `Heights are proportional to shadow lengths: ${h} × ${S} ÷ ${s} = ${rd(h * S / s, 2)} m.`); },
    r => { const k = r.pick([2, 3]), A = r.int(20, 60); return B(`A photograph has an area of ${A} cm². It is enlarged so that every length is multiplied by ${k}. Find the area of the enlarged photograph in cm².`, A * k * k, `Area scale factor = ${k * k}, so the area is ${A} × ${k * k} = ${A * k * k} cm².`); },
    r => { const k = r.pick([2, 4, 5]), d = r.int(6, 15); return B(`On a map with scale 1 : ${k * 10000}, two towns are ${d} cm apart. Find the actual distance in kilometres.`, d * k / 10, `${d} × ${k * 10000} cm = ${d * k * 10000} cm = ${d * k / 10} km.`); },
    r => { const a = r.int(4, 9), b = r.int(2, 5), c = r.int(3, 6); return B(`A pole of height ${a} m casts a shadow of ${b} m. A building casts a shadow of ${b * c} m at the same time. Find the height of the building in metres.`, a * c, `Scale factor = ${b * c} ÷ ${b} = ${c}. Height = ${a} × ${c} = ${a * c} m.`); },
    r => { const L = r.int(5, 12), k = r.pick([20, 25, 40, 50]); return B(`A model car is made to a scale of 1 : ${k}. The model is ${L} cm long. Find the length of the real car in metres.`, L * k / 100, `${L} × ${k} = ${L * k} cm = ${L * k / 100} m.`); },
    r => { const a = r.int(2, 3), V = r.int(2, 8) * 10; return B(`Two similar bottles have heights in the ratio ${a} : ${a + 1}. The smaller bottle holds ${V * a ** 3} ml. How many ml does the larger bottle hold?`, V * (a + 1) ** 3, `Volume ratio ${a ** 3} : ${(a + 1) ** 3}. Volume = ${V * a ** 3} ÷ ${a ** 3} × ${(a + 1) ** 3} = ${V * (a + 1) ** 3} ml.`); }
  ]});

  /* ---- Pythagoras' theorem ---- */
  g.push({id: 'G3.2.pythagoras-theorem.1', plain: [
    r => { const [a, b, c] = tri(r); return B(`A right-angled triangle has shorter sides ${a} cm and ${b} cm. Find the length of the hypotenuse in cm.`, c, `$\\sqrt{${a}^2 + ${b}^2} = \\sqrt{${a * a + b * b}} = ${c}$ cm.`); },
    r => { const [a, b, c] = tri(r); return B(`A right-angled triangle has hypotenuse ${c} cm and one side ${a} cm. Find the other side in cm.`, b, `$\\sqrt{${c}^2 - ${a}^2} = \\sqrt{${c * c - a * a}} = ${b}$ cm.`); },
    r => { const a = r.int(2, 9), b = r.int(2, 9); return B(`A right-angled triangle has shorter sides ${a} cm and ${b} cm. Find the hypotenuse correct to 1 decimal place, in cm.`, rd(Math.sqrt(a * a + b * b), 1), `$\\sqrt{${a * a + b * b}} = ${rd(Math.sqrt(a * a + b * b), 2)}$ ≈ ${rd(Math.sqrt(a * a + b * b), 1)} cm.`); },
    r => { const [a, b, c] = tri(r); return B(`A triangle has sides ${a} cm, ${b} cm and ${c} cm. Is it right-angled? Type 1 for yes or 0 for no.`, 1, `$${a}^2 + ${b}^2 = ${a * a + b * b} = ${c}^2$, so it is right-angled.`); },
    r => { const a = r.int(5, 12), b = r.int(6, 14), c = Math.round(Math.sqrt(a * a + b * b)) + 1; if (a * a + b * b === c * c) return null; return B(`A triangle has sides ${a} cm, ${b} cm and ${c} cm. Is it right-angled? Type 1 for yes or 0 for no.`, 0, `$${a}^2 + ${b}^2 = ${a * a + b * b}$ but $${c}^2 = ${c * c}$, so it is not right-angled.`); },
    r => { const [a, b, c] = tri(r); return B(`Find the area of a right-angled triangle with hypotenuse ${c} cm and one shorter side ${a} cm, in cm².`, a * b / 2, `Other side = ${b} cm. Area = ½ × ${a} × ${b} = ${a * b / 2} cm².`); },
    r => { const [a, b, c] = tri(r); return B(`Find the perimeter of a right-angled triangle with shorter sides ${a} cm and ${b} cm, in cm.`, a + b + c, `Hypotenuse = ${c} cm. Perimeter = ${a} + ${b} + ${c} = ${a + b + c} cm.`); },
    r => { const x1 = r.int(0, 3), y1 = r.int(0, 3), t = r.pick([[3, 4, 5], [6, 8, 10], [5, 12, 13]]); return B(`Find the distance between the points $(${x1}, ${y1})$ and $(${x1 + t[0]}, ${y1 + t[1]})$.`, t[2], `$\\sqrt{${t[0]}^2 + ${t[1]}^2} = ${t[2]}$.`); },
    r => { const [a, b, c] = tri(r); return B(`A rectangle is ${a} cm long and ${b} cm wide. Find the length of its diagonal in cm.`, c, `Diagonal = $\\sqrt{${a}^2 + ${b}^2} = ${c}$ cm.`); },
    r => { const s = r.int(3, 12); return B(`Find the length of the diagonal of a square of side ${s} cm, correct to 1 decimal place, in cm.`, rd(s * Math.SQRT2, 1), `$\\sqrt{${s}^2 + ${s}^2} = ${rd(s * Math.SQRT2, 2)}$ ≈ ${rd(s * Math.SQRT2, 1)} cm.`); },
    r => { const [a, b, c] = tri(r); return B(`An isosceles triangle has equal sides ${c} cm and base ${2 * a} cm. Find its height in cm.`, b, `Half the base = ${a}. Height = $\\sqrt{${c}^2 - ${a}^2} = ${b}$ cm.`); },
    r => { const a = r.int(2, 8) * 2; return B(`An equilateral triangle has sides ${a} cm. Find its height correct to 1 decimal place, in cm.`, rd(a * Math.sqrt(3) / 2, 1), `Height = $\\sqrt{${a}^2 - ${a / 2}^2} = ${rd(a * Math.sqrt(3) / 2, 2)}$ ≈ ${rd(a * Math.sqrt(3) / 2, 1)} cm.`); },
    r => { const [a, b, c] = tri(r); return B(`In triangle $ABC$, $\\angle B = 90°$, $AB = ${a}$ cm and $AC = ${c}$ cm. Find $BC$ in cm.`, b, `$BC = \\sqrt{${c}^2 - ${a}^2} = ${b}$ cm.`); },
    r => { const a = r.int(3, 10), b = r.int(3, 10); return B(`In a right-angled triangle, the hypotenuse squared is ${a * a + b * b} and one shorter side is ${a} cm. Find the other shorter side in cm.`, b, `$${a * a + b * b} - ${a * a} = ${b * b}$, so the side is ${b} cm.`); },
    r => { const k = r.int(2, 5), t = r.pick([[3, 4, 5], [5, 12, 13]]); return B(`The sides of a right-angled triangle are in the ratio ${t.join(' : ')}. The shortest side is ${t[0] * k} cm. Find the hypotenuse in cm.`, t[2] * k, `Each part is ${k} cm, so the hypotenuse is ${t[2]} × ${k} = ${t[2] * k} cm.`); }
  ], word: [
    r => { const [a, b, c] = tri(r); return B(`A ladder ${c} m long leans against a vertical wall. Its foot is ${a} m from the wall. How high up the wall does it reach, in metres?`, b, `Height = $\\sqrt{${c}^2 - ${a}^2} = ${b}$ m.`); },
    r => { const [a, b, c] = tri(r); return B(`A boat sails ${a} km north and then ${b} km east. How far is it from its starting point, in km?`, c, `Distance = $\\sqrt{${a}^2 + ${b}^2} = ${c}$ km.`); },
    r => { const [a, b, c] = tri(r); return B(`A wire is stretched from the top of a vertical pole ${b} m high to a point on the ground ${a} m from the foot of the pole. Find the length of the wire in metres.`, c, `Length = $\\sqrt{${a}^2 + ${b}^2} = ${c}$ m.`); },
    r => { const [a, b, c] = tri(r); return B(`A rectangular field is ${b} m long and ${a} m wide. Sam walks along two sides while Mei walks along the diagonal. How many metres shorter is Mei's route?`, a + b - c, `Sam walks ${a + b} m, Mei walks ${c} m. Difference = ${a + b - c} m.`); },
    r => { const a = r.int(20, 40), b = r.int(12, 30); return B(`A television screen is ${a} cm wide and ${b} cm high. Find the length of its diagonal correct to 1 decimal place, in cm.`, rd(Math.sqrt(a * a + b * b), 1), `$\\sqrt{${a}^2 + ${b}^2} = ${rd(Math.sqrt(a * a + b * b), 2)}$ ≈ ${rd(Math.sqrt(a * a + b * b), 1)} cm.`); },
    r => { const [a, b, c] = tri(r); return B(`Two cyclists leave a junction at the same time. One cycles ${a} km due west and the other ${b} km due south. How far apart are they, in km?`, c, `Distance = $\\sqrt{${a}^2 + ${b}^2} = ${c}$ km.`); }
  ]});

  /* ---- Trigonometric ratios ---- */
  g.push({id: 'G3.2.trigonometric-ratios.1', plain: [
    r => { const [o, a, h] = tri(r); return B(`In a right-angled triangle, the side opposite angle $\\theta$ is ${o} cm and the hypotenuse is ${h} cm. Find $\\sin\\theta$ correct to 3 decimal places.`, rd(o / h, 3), `$\\sin\\theta = \\dfrac{${o}}{${h}} = ${rd(o / h, 3)}$.`); },
    r => { const [o, a, h] = tri(r); return B(`In a right-angled triangle, the side adjacent to angle $\\theta$ is ${a} cm and the hypotenuse is ${h} cm. Find $\\cos\\theta$ correct to 3 decimal places.`, rd(a / h, 3), `$\\cos\\theta = \\dfrac{${a}}{${h}} = ${rd(a / h, 3)}$.`); },
    r => { const [o, a, h] = tri(r); return B(`In a right-angled triangle, the sides opposite and adjacent to angle $\\theta$ are ${o} cm and ${a} cm. Find $\\tan\\theta$ correct to 3 decimal places.`, rd(o / a, 3), `$\\tan\\theta = \\dfrac{${o}}{${a}} = ${rd(o / a, 3)}$.`); },
    r => { const A = r.int(20, 70), h = r.int(8, 20); return B(`In triangle $ABC$, $\\angle B = 90°$, $\\angle A = ${A}°$ and $AC = ${h}$ cm. Find $BC$ correct to 1 decimal place, in cm.`, rd(h * sinD(A), 1), `$BC = ${h} \\sin ${A}° = ${rd(h * sinD(A), 2)}$ ≈ ${rd(h * sinD(A), 1)} cm.`); },
    r => { const A = r.int(20, 70), h = r.int(8, 20); return B(`In triangle $ABC$, $\\angle B = 90°$, $\\angle A = ${A}°$ and $AC = ${h}$ cm. Find $AB$ correct to 1 decimal place, in cm.`, rd(h * cosD(A), 1), `$AB = ${h} \\cos ${A}° = ${rd(h * cosD(A), 2)}$ ≈ ${rd(h * cosD(A), 1)} cm.`); },
    r => { const A = r.int(20, 70), b = r.int(6, 18); return B(`In triangle $ABC$, $\\angle B = 90°$, $\\angle A = ${A}°$ and $AB = ${b}$ cm. Find $BC$ correct to 1 decimal place, in cm.`, rd(b * tanD(A), 1), `$BC = ${b} \\tan ${A}° = ${rd(b * tanD(A), 2)}$ ≈ ${rd(b * tanD(A), 1)} cm.`); },
    r => { const [o, a, h] = tri(r); return B(`In a right-angled triangle, $\\sin\\theta = \\dfrac{${o}}{${h}}$. Find $\\theta$ correct to 1 decimal place, in degrees.`, rd(asinD(o / h), 1), `$\\theta = \\sin^{-1}\\left(\\dfrac{${o}}{${h}}\\right) = ${rd(asinD(o / h), 2)}°$ ≈ ${rd(asinD(o / h), 1)}°.`); },
    r => { const [o, a, h] = tri(r); return B(`In a right-angled triangle, the opposite and adjacent sides to $\\theta$ are ${o} cm and ${a} cm. Find $\\theta$ correct to 1 decimal place, in degrees.`, rd(atanD(o / a), 1), `$\\theta = \\tan^{-1}\\left(\\dfrac{${o}}{${a}}\\right) = ${rd(atanD(o / a), 2)}°$ ≈ ${rd(atanD(o / a), 1)}°.`); },
    r => { const A = r.int(15, 75); return B(`Find $\\sin ${A}°$ correct to 3 decimal places.`, rd(sinD(A), 3), `Use a calculator: $\\sin ${A}° = ${rd(sinD(A), 4)}$ ≈ ${rd(sinD(A), 3)}.`); },
    r => { const A = r.int(15, 75); return B(`Find $\\cos ${A}°$ correct to 3 decimal places.`, rd(cosD(A), 3), `Use a calculator: $\\cos ${A}° = ${rd(cosD(A), 4)}$ ≈ ${rd(cosD(A), 3)}.`); },
    r => { const A = r.int(15, 75); return B(`Find $\\tan ${A}°$ correct to 3 decimal places.`, rd(tanD(A), 3), `Use a calculator: $\\tan ${A}° = ${rd(tanD(A), 4)}$ ≈ ${rd(tanD(A), 3)}.`); },
    r => { const A = r.int(15, 75); return B(`In a right-angled triangle, one acute angle is ${A}°. Find the other acute angle in degrees.`, 90 - A, `90 − ${A} = ${90 - A}°.`); },
    r => { const A = r.int(20, 70), o = r.int(5, 15); return B(`In a right-angled triangle, the side opposite a ${A}° angle is ${o} cm. Find the hypotenuse correct to 1 decimal place, in cm.`, rd(o / sinD(A), 1), `Hypotenuse = ${o} ÷ $\\sin ${A}°$ = ${rd(o / sinD(A), 2)} ≈ ${rd(o / sinD(A), 1)} cm.`); },
    r => { const A = r.int(20, 70), a = r.int(5, 15); return B(`In a right-angled triangle, the side adjacent to a ${A}° angle is ${a} cm. Find the hypotenuse correct to 1 decimal place, in cm.`, rd(a / cosD(A), 1), `Hypotenuse = ${a} ÷ $\\cos ${A}°$ = ${rd(a / cosD(A), 2)} ≈ ${rd(a / cosD(A), 1)} cm.`); },
    r => { const [o, a, h] = tri(r); return B(`In a right-angled triangle, the adjacent side to $\\theta$ is ${a} cm and the hypotenuse is ${h} cm. Find $\\theta$ correct to 1 decimal place, in degrees.`, rd(acosD(a / h), 1), `$\\theta = \\cos^{-1}\\left(\\dfrac{${a}}{${h}}\\right) = ${rd(acosD(a / h), 2)}°$ ≈ ${rd(acosD(a / h), 1)}°.`); }
  ], word: [
    r => { const A = r.int(55, 75), L = r.int(4, 8); return B(`A ladder ${L} m long leans against a wall and makes an angle of ${A}° with the ground. How high up the wall does it reach, correct to 1 decimal place, in metres?`, rd(L * sinD(A), 1), `Height = ${L} sin ${A}° = ${rd(L * sinD(A), 2)} ≈ ${rd(L * sinD(A), 1)} m.`); },
    r => { const h = r.int(1, 3), d = r.int(8, 20); return B(`A ramp rises ${h} m over a horizontal distance of ${d} m. Find the angle the ramp makes with the horizontal, correct to 1 decimal place, in degrees.`, rd(atanD(h / d), 1), `$\\tan\\theta = \\dfrac{${h}}{${d}}$, so $\\theta = ${rd(atanD(h / d), 2)}°$ ≈ ${rd(atanD(h / d), 1)}°.`); },
    r => { const L = r.int(10, 30), A = r.int(25, 60); return B(`A kite string of length ${L} m makes an angle of ${A}° with the horizontal ground (assume the string is straight). Find the height of the kite above the ground correct to 1 decimal place, in metres.`, rd(L * sinD(A), 1), `Height = ${L} sin ${A}° = ${rd(L * sinD(A), 2)} ≈ ${rd(L * sinD(A), 1)} m.`); },
    r => { const A = r.int(30, 60), h = r.int(5, 12); return B(`A flagpole ${h} m tall casts a shadow on level ground when the Sun's rays make an angle of ${A}° with the ground. Find the length of the shadow correct to 1 decimal place, in metres.`, rd(h / tanD(A), 1), `Shadow = ${h} ÷ tan ${A}° = ${rd(h / tanD(A), 2)} ≈ ${rd(h / tanD(A), 1)} m.`); },
    r => { const A = r.int(25, 55), d = r.int(10, 25); return B(`A staircase rises at ${A}° to the horizontal. A person walks ${d} m along the slope. How far, correct to 1 decimal place, has the person risen vertically, in metres?`, rd(d * sinD(A), 1), `Rise = ${d} sin ${A}° = ${rd(d * sinD(A), 2)} ≈ ${rd(d * sinD(A), 1)} m.`); },
    r => { const a = r.int(6, 12), b = r.int(4, 9); return B(`A rectangular sign is ${a} m wide and ${b} m high. A line is drawn along its diagonal. Find the angle the diagonal makes with the base, correct to 1 decimal place, in degrees.`, rd(atanD(b / a), 1), `$\\tan\\theta = \\dfrac{${b}}{${a}}$, so $\\theta = ${rd(atanD(b / a), 2)}°$ ≈ ${rd(atanD(b / a), 1)}°.`); }
  ]});

  /* ---- Applications of trigonometry (elevation and depression) ---- */
  g.push({id: 'G3.2.trigonometric-ratios.2', plain: [
    r => { const A = r.int(20, 70); return B(`The angle of elevation of a point $A$ from a point $B$ is ${A}°. Find the angle of depression of $B$ from $A$ in degrees.`, A, 'The angle of depression equals the angle of elevation (alternate angles).'); },
    r => { const A = r.int(25, 55), h = r.int(20, 60); return B(`From the top of a ${h} m tower, the angle of depression of a point on the ground is ${A}°. Find the straight-line distance from the top of the tower to the point, correct to 1 decimal place, in metres.`, rd(h / sinD(A), 1), `Distance = ${h} ÷ sin ${A}° = ${rd(h / sinD(A), 2)} ≈ ${rd(h / sinD(A), 1)} m.`); },
    r => { const A = r.int(20, 70), d = r.int(20, 60); return B(`From a point on level ground ${d} m from the foot of a tower, the angle of elevation of the top is ${A}°. Find the height of the tower correct to 1 decimal place, in metres.`, rd(d * tanD(A), 1), `Height = ${d} tan ${A}° = ${rd(d * tanD(A), 2)} ≈ ${rd(d * tanD(A), 1)} m.`); },
    r => { const A = r.int(20, 60), h = r.int(15, 50); return B(`The angle of elevation of the top of a building ${h} m high from a point $P$ on the ground is ${A}°. Find the distance of $P$ from the foot of the building correct to 1 decimal place, in metres.`, rd(h / tanD(A), 1), `Distance = ${h} ÷ tan ${A}° = ${rd(h / tanD(A), 2)} ≈ ${rd(h / tanD(A), 1)} m.`); },
    r => { const h = r.int(10, 40), d = r.int(15, 50); return B(`From the top of a ${h} m cliff, a boat is ${d} m from the foot of the cliff. Find the angle of depression of the boat from the top of the cliff, correct to 1 decimal place, in degrees.`, rd(atanD(h / d), 1), `$\\tan\\theta = \\dfrac{${h}}{${d}}$, so $\\theta = ${rd(atanD(h / d), 2)}°$ ≈ ${rd(atanD(h / d), 1)}°.`); },
    r => { const A = r.int(20, 60), h = r.int(20, 60); return B(`From a window ${h} m above the ground, the angle of depression of a car on the road is ${A}°. Find the horizontal distance of the car from the building correct to 1 decimal place, in metres.`, rd(h / tanD(A), 1), `Distance = ${h} ÷ tan ${A}° = ${rd(h / tanD(A), 2)} ≈ ${rd(h / tanD(A), 1)} m.`); },
    r => { const h = r.int(8, 20), d = r.int(10, 30); return B(`The top of a tree ${h} m tall is seen from a point ${d} m away on level ground. Find the angle of elevation of the top of the tree, correct to 1 decimal place, in degrees.`, rd(atanD(h / d), 1), `$\\tan\\theta = \\dfrac{${h}}{${d}}$, so $\\theta = ${rd(atanD(h / d), 2)}°$ ≈ ${rd(atanD(h / d), 1)}°.`); },
    r => { const A = r.int(20, 60), L = r.int(10, 40); return B(`A cable of length ${L} m runs from the top of a mast to the ground at an angle of elevation ${A}° from the ground. Find the height of the mast correct to 1 decimal place, in metres.`, rd(L * sinD(A), 1), `Height = ${L} sin ${A}° = ${rd(L * sinD(A), 2)} ≈ ${rd(L * sinD(A), 1)} m.`); },
    r => { const A = r.int(20, 60), L = r.int(10, 40); return B(`A cable of length ${L} m runs from the top of a mast to the ground at an angle of ${A}° with the ground. How far is the foot of the cable from the base of the mast, correct to 1 decimal place, in metres?`, rd(L * cosD(A), 1), `Distance = ${L} cos ${A}° = ${rd(L * cosD(A), 2)} ≈ ${rd(L * cosD(A), 1)} m.`); },
    r => { const A = r.int(30, 60); return B(`The angle of elevation of a bird from a boy is ${A}°. Find the angle of depression of the boy from the bird in degrees.`, A, 'Alternate angles are equal.'); },
    r => { const A = r.int(25, 55), d = r.int(40, 90), h = r.int(1, 2); return B(`Ali, whose eye level is ${h} m above the ground, stands ${d} m from a building. The angle of elevation of the top is ${A}°. Find the height of the building correct to 1 decimal place, in metres.`, rd(d * tanD(A) + h, 1), `Height above eye = ${d} tan ${A}° = ${rd(d * tanD(A), 2)}. Add ${h} m: ${rd(d * tanD(A) + h, 1)} m.`); },
    r => { const h = r.int(30, 80), A = r.int(25, 55), Bn = A + r.int(10, 20); return B(`From the top of a ${h} m tower, the angle of depression of a car is ${A}°. Find the horizontal distance of the car from the tower correct to the nearest metre.`, Math.round(h / tanD(A)), `Distance = ${h} ÷ tan ${A}° = ${rd(h / tanD(A), 2)} ≈ ${Math.round(h / tanD(A))} m.`); },
    r => { const A = r.int(25, 60), x = r.int(20, 60); return B(`A vertical pole stands on level ground. From a point ${x} m away the angle of elevation of the top is ${A}°. Find the straight-line distance from the point to the top of the pole correct to 1 decimal place, in metres.`, rd(x / cosD(A), 1), `Distance = ${x} ÷ cos ${A}° = ${rd(x / cosD(A), 2)} ≈ ${rd(x / cosD(A), 1)} m.`); },
    r => { const A = r.int(25, 55), h = r.int(10, 30); return B(`The angle of depression of a boat from the top of a lighthouse ${h} m high is ${A}°. Find the angle of elevation of the top of the lighthouse from the boat in degrees.`, A, 'The angle of elevation equals the angle of depression (alternate angles).'); }
  ], word: [
    r => { const A = r.int(25, 60), h = r.int(20, 80); return B(`A kite is flying at a height of ${h} m. A boy sees it at an angle of elevation of ${A}°. Find the horizontal distance of the kite from the boy, correct to the nearest metre.`, Math.round(h / tanD(A)), `Distance = ${h} ÷ tan ${A}° = ${rd(h / tanD(A), 2)} ≈ ${Math.round(h / tanD(A))} m.`); },
    r => { const A = r.int(30, 50), d = r.int(30, 80); return B(`A surveyor stands ${d} m from the base of a hill and measures the angle of elevation of the top as ${A}°. Find the height of the hill correct to the nearest metre.`, Math.round(d * tanD(A)), `Height = ${d} tan ${A}° = ${rd(d * tanD(A), 2)} ≈ ${Math.round(d * tanD(A))} m.`); },
    r => { const h = r.int(40, 100), A = r.int(20, 40); return B(`From the top of a lighthouse ${h} m high, the angle of depression of a ship is ${A}°. How far is the ship from the foot of the lighthouse, correct to the nearest metre?`, Math.round(h / tanD(A)), `Distance = ${h} ÷ tan ${A}° = ${rd(h / tanD(A), 2)} ≈ ${Math.round(h / tanD(A))} m.`); },
    r => { const A = r.int(35, 55), d = r.int(20, 50); return B(`A tree casts no shadow when the Sun is overhead. A man stands ${d} m from a tree and sees the top at an angle of elevation of ${A}°. His eyes are 1.6 m above the ground. Find the height of the tree, correct to 1 decimal place, in metres.`, rd(d * tanD(A) + 1.6, 1), `Height = ${d} tan ${A}° + 1.6 = ${rd(d * tanD(A), 2)} + 1.6 = ${rd(d * tanD(A) + 1.6, 1)} m.`); },
    r => { const A = r.int(30, 60), L = r.int(5, 12); return B(`A ladder ${L} m long leans against a wall. The angle of elevation of the top of the ladder from its foot is ${A}°. Find the height of the top of the ladder above the ground, correct to 1 decimal place, in metres.`, rd(L * sinD(A), 1), `Height = ${L} sin ${A}° = ${rd(L * sinD(A), 2)} ≈ ${rd(L * sinD(A), 1)} m.`); },
    r => { const A = r.int(20, 45), h = r.int(10, 30), d = r.int(20, 50); return B(`From a balcony ${h} m above the ground, the angle of depression of a car is ${A}°. Find the straight-line distance from the balcony to the car, correct to 1 decimal place, in metres.`, rd(h / sinD(A), 1), `Distance = ${h} ÷ sin ${A}° = ${rd(h / sinD(A), 2)} ≈ ${rd(h / sinD(A), 1)} m.`); }
  ]});

  /* ---- Pyramids ---- */
  g.push({id: 'G3.2.volume-and-surface-area-of-pyramids-cones-and-spheres.1', plain: [
    r => { const s = r.int(3, 12), h = r.int(3, 15); return B(`Find the volume of a pyramid with a square base of side ${s} cm and height ${h} cm, correct to 1 decimal place, in cm³.`, rd(s * s * h / 3, 1), `$V = \\dfrac{1}{3} \\times ${s * s} \\times ${h} = ${rd(s * s * h / 3, 2)}$ ≈ ${rd(s * s * h / 3, 1)} cm³.`); },
    r => { const l = r.int(4, 12), w = r.int(3, 9), h = r.int(3, 6) * 3; return B(`A pyramid has a rectangular base ${l} cm by ${w} cm and height ${h} cm. Find its volume in cm³.`, l * w * h / 3, `$V = \\dfrac{1}{3} \\times ${l * w} \\times ${h} = ${l * w * h / 3}$ cm³.`); },
    r => { const A = r.int(2, 12) * 3, h = r.int(3, 9); return B(`A pyramid has a base area of ${A} cm² and height ${h} cm. Find its volume in cm³.`, A * h / 3, `$V = \\dfrac{1}{3} \\times ${A} \\times ${h} = ${A * h / 3}$ cm³.`); },
    r => { const V = r.int(2, 9) * 30, A = r.int(5, 10) * 6; if ((3 * V) % A) return null; return B(`A pyramid has volume ${V} cm³ and base area ${A} cm². Find its height in cm.`, 3 * V / A, `$h = \\dfrac{3V}{A} = \\dfrac{${3 * V}}{${A}} = ${3 * V / A}$ cm.`); },
    r => { const [a, b, c] = tri(r); return B(`A square pyramid has a base of side ${2 * a} cm and a vertical height of ${b} cm. Find its slant height (the height of a triangular face) in cm.`, c, `Slant height = $\\sqrt{${a}^2 + ${b}^2} = ${c}$ cm.`); },
    r => { const [a, b, c] = tri(r); return B(`A square pyramid has a base of side ${2 * a} cm and a slant height of ${c} cm. Find its vertical height in cm.`, b, `Vertical height = $\\sqrt{${c}^2 - ${a}^2} = ${b}$ cm.`); },
    r => { const [a, b, c] = tri(r); return B(`A square pyramid has a base of side ${2 * a} cm and a slant height of ${c} cm. Find the total surface area in cm².`, 4 * a * a + 2 * (2 * a) * c, `Base = ${(2 * a) ** 2}. Each triangular face = ½ × ${2 * a} × ${c} = ${a * c}, four faces = ${4 * a * c}. Total = ${4 * a * a + 4 * a * c} cm².`); },
    r => { const s = r.int(4, 10), l = r.int(5, 12); return B(`Find the area of the four triangular faces of a square pyramid with base side ${s} cm and slant height ${l} cm, in cm².`, 2 * s * l, `4 × ½ × ${s} × ${l} = ${2 * s * l} cm².`); },
    r => { const e = r.int(3, 9), h = r.int(4, 12); return B(`A cube of edge ${e} cm has a pyramid on top of one face with the same base and height ${h * 3} cm. Find the volume of the pyramid in cm³.`, e * e * h, `$V = \\dfrac{1}{3} \\times ${e * e} \\times ${h * 3} = ${e * e * h}$ cm³.`); },
    r => { const s = r.int(4, 10), h = r.int(6, 15), k = r.pick([2, 3]); return B(`The height of a square pyramid is multiplied by ${k} while the base stays the same. By what factor is its volume multiplied?`, k, `The volume is proportional to the height, so it is multiplied by ${k}.`); },
    r => { const a = r.int(3, 8), b = r.int(4, 9), h = r.int(6, 15); return B(`A pyramid has a triangular base with base ${a} cm and height ${b} cm. The height of the pyramid is ${h} cm. Find its volume in cm³.`, a * b * h / 6, `Base area = ½ × ${a} × ${b} = ${a * b / 2} cm². V = ⅓ × ${a * b / 2} × ${h} = ${a * b * h / 6} cm³.`); },
    r => { const s = r.int(6, 14), l = r.int(8, 18); return B(`A square pyramid has base side ${s} cm and slant height ${l} cm. Find the area of one triangular face in cm².`, s * l / 2, `½ × ${s} × ${l} = ${s * l / 2} cm².`); },
    r => { const [a, b, c] = tri(r); return B(`A square pyramid has a base of side ${2 * a} m and a vertical height of ${b} m. Find its volume in m³, correct to 1 decimal place.`, rd((2 * a) ** 2 * b / 3, 1), `$V = \\dfrac{1}{3} \\times ${(2 * a) ** 2} \\times ${b} = ${rd((2 * a) ** 2 * b / 3, 2)}$ ≈ ${rd((2 * a) ** 2 * b / 3, 1)} m³.`); },
    r => { const s = r.int(3, 9), h = r.int(4, 12); return B(`Find the volume of a regular square pyramid whose base side is ${s} cm and whose height is ${h} cm when the volume is expressed in cm³ correct to the nearest whole number.`, Math.round(s * s * h / 3), `$V = \\dfrac{1}{3} \\times ${s * s} \\times ${h} = ${rd(s * s * h / 3, 2)}$ ≈ ${Math.round(s * s * h / 3)} cm³.`); }
  ], word: [
    r => { const [a, b, c] = tri(r); return B(`A tent is a square pyramid with base side ${2 * a} m and height ${b} m. Find the volume of air inside the tent in m³, correct to 1 decimal place.`, rd((2 * a) ** 2 * b / 3, 1), `$V = \\dfrac{1}{3} \\times ${(2 * a) ** 2} \\times ${b} = ${rd((2 * a) ** 2 * b / 3, 2)}$ ≈ ${rd((2 * a) ** 2 * b / 3, 1)} m³.`); },
    r => { const s = r.int(30, 60), h = r.int(40, 100); return B(`A glass paperweight is a square pyramid with base side ${s} mm and height ${h} mm. Find its volume in mm³, correct to the nearest whole number.`, Math.round(s * s * h / 3), `$V = \\dfrac{1}{3} \\times ${s * s} \\times ${h} = ${rd(s * s * h / 3, 2)}$ ≈ ${Math.round(s * s * h / 3)} mm³.`); },
    r => { const [a, b, c] = tri(r); return B(`The roof of a tower is a square pyramid with base side ${2 * a} m and slant height ${c} m. Find the area of the roof in m², if the roof covers the four triangular faces.`, 4 * a * c, `4 × ½ × ${2 * a} × ${c} = ${4 * a * c} m².`); },
    r => { const A = r.int(2, 8) * 10, h = r.int(6, 15) * 3; return B(`A monument is a pyramid with a square base of area ${A} m² and a height of ${h} m. Find its volume in m³.`, A * h / 3, `$V = \\dfrac{1}{3} \\times ${A} \\times ${h} = ${A * h / 3}$ m³.`); },
    r => { const s = r.int(8, 20), V = s * s * 3 * r.int(2, 6); return B(`A pyramid-shaped container has a square base of side ${s} cm and holds ${V} cm³ when full. Find its height in cm.`, 3 * V / (s * s), `$h = \\dfrac{3V}{${s * s}} = ${3 * V / (s * s)}$ cm.`); },
    r => { const [a, b, c] = tri(r), cost = r.int(2, 4); return B(`The four triangular faces of a pyramid-shaped hat are made of felt costing \\$${cost} per 100 cm². The base is ${2 * a} cm square and the slant height is ${c} cm. Find the area of felt needed in cm².`, 4 * a * c, `Area of four faces = 4 × ½ × ${2 * a} × ${c} = ${4 * a * c} cm².`); }
  ]});

  /* ---- Cones ---- */
  g.push({id: 'G3.2.volume-and-surface-area-of-pyramids-cones-and-spheres.2', plain: [
    r => { const R = r.int(2, 9), h = r.int(3, 14); return B(`Find the volume of a cone of radius ${R} cm and height ${h} cm, correct to 1 decimal place, in cm³.`, rd(PI * R * R * h / 3, 1), `$V = \\dfrac{1}{3}\\pi(${R})^2(${h}) = ${rd(PI * R * R * h / 3, 2)}$ ≈ ${rd(PI * R * R * h / 3, 1)} cm³.`); },
    r => { const [a, b, c] = tri(r); return B(`A cone has radius ${a} cm and height ${b} cm. Find its slant height in cm.`, c, `$l = \\sqrt{${a}^2 + ${b}^2} = ${c}$ cm.`); },
    r => { const [a, b, c] = tri(r); return B(`A cone has radius ${a} cm and slant height ${c} cm. Find its height in cm.`, b, `$h = \\sqrt{${c}^2 - ${a}^2} = ${b}$ cm.`); },
    r => { const [a, b, c] = tri(r); return B(`A cone has radius ${a} cm and slant height ${c} cm. Find its curved surface area, correct to 1 decimal place, in cm².`, rd(PI * a * c, 1), `$\\pi r l = \\pi(${a})(${c}) = ${rd(PI * a * c, 2)}$ ≈ ${rd(PI * a * c, 1)} cm².`); },
    r => { const [a, b, c] = tri(r); return B(`A closed cone has radius ${a} cm and slant height ${c} cm. Find its total surface area, correct to 1 decimal place, in cm².`, rd(PI * a * (a + c), 1), `$\\pi r(r + l) = \\pi(${a})(${a + c}) = ${rd(PI * a * (a + c), 2)}$ ≈ ${rd(PI * a * (a + c), 1)} cm².`); },
    r => { const R = r.int(3, 8), h = r.int(6, 15); return B(`A cone has a base diameter of ${2 * R} cm and a height of ${h} cm. Find its volume correct to the nearest whole number, in cm³.`, Math.round(PI * R * R * h / 3), `Radius = ${R}. $V = \\dfrac{1}{3}\\pi(${R})^2(${h}) = ${rd(PI * R * R * h / 3, 2)}$ ≈ ${Math.round(PI * R * R * h / 3)} cm³.`); },
    r => { const R = r.int(3, 8), V = r.int(5, 20) * 10; return B(`A cone of radius ${R} cm has a volume of ${V} cm³. Find its height correct to 1 decimal place, in cm.`, rd(3 * V / (PI * R * R), 1), `$h = \\dfrac{3V}{\\pi r^2} = \\dfrac{${3 * V}}{\\pi(${R})^2} = ${rd(3 * V / (PI * R * R), 2)}$ ≈ ${rd(3 * V / (PI * R * R), 1)} cm.`); },
    r => { const R = r.int(2, 8), l = r.int(R + 2, R + 9); return B(`A cone has radius ${R} cm and slant height ${l} cm. Find the area of its curved surface in terms of $\\pi$: give the coefficient of $\\pi$.`, R * l, `Curved surface area = $\\pi(${R})(${l}) = ${R * l}\\pi$ cm².`); },
    r => { const R = r.int(3, 8), h = r.int(4, 12), k = r.pick([2, 3]); return B(`A cone has radius ${R} cm and height ${h} cm. If the radius is multiplied by ${k} and the height stays the same, by what factor is the volume multiplied?`, k * k, `Volume depends on $r^2$, so it is multiplied by ${k * k}.`); },
    r => { const L = r.int(8, 15), a = r.pick([90, 120, 180, 240]); const R = L * a / 360; if (!Number.isInteger(R * 2) ) return null; return B(`A sector of a circle with radius ${L} cm and angle ${a}° is rolled up to form a cone. Find the radius of the base of the cone in cm.`, R, `Arc length = $\\dfrac{${a}}{360} \\times 2\\pi(${L})$, and this equals $2\\pi r$, so $r = ${L} \\times \\dfrac{${a}}{360} = ${R}$ cm.`); },
    r => { const R = r.int(3, 9), l = r.int(R + 2, R + 8); return B(`A cone has radius ${R} cm and slant height ${l} cm. Find the area of its curved surface correct to the nearest whole number, in cm².`, Math.round(PI * R * l), `$\\pi(${R})(${l}) = ${rd(PI * R * l, 2)}$ ≈ ${Math.round(PI * R * l)} cm².`); },
    r => { const R = r.int(3, 9), h = r.int(6, 12); return B(`A cylinder and a cone have the same radius ${R} cm and the same height ${h} cm. How many times the volume of the cone is the volume of the cylinder?`, 3, 'The cone has one third of the volume of the cylinder.'); },
    r => { const [a, b, c] = tri(r); return B(`A cone has base radius ${a} cm and vertical height ${b} cm. Find its curved surface area, correct to the nearest whole number, in cm².`, Math.round(PI * a * c), `Slant height = ${c}. $\\pi(${a})(${c}) = ${rd(PI * a * c, 2)}$ ≈ ${Math.round(PI * a * c)} cm².`); },
    r => { const R = r.int(2, 6), h = r.int(2, 5) * 3; return B(`A cone of radius ${R} cm and height ${h} cm is full of water. The water is poured into a cylinder of the same radius. Find the depth of the water in the cylinder, in cm.`, h / 3, `The cone's volume is ⅓πR²h, and in the cylinder this fills depth ${h} ÷ 3 = ${h / 3} cm.`); },
    r => { const R = r.int(4, 10), l = r.int(8, 15); return B(`The curved surface area of a cone is ${R * l}$\\pi$ cm² and its radius is ${R} cm. Find the slant height in cm.`, l, `$\\pi r l = ${R * l}\\pi$ so $l = \\dfrac{${R * l}}{${R}} = ${l}$ cm.`); }
  ], word: [
    r => { const R = r.int(3, 5), h = r.int(8, 15); return B(`An ice cream cone has a radius of ${R} cm and a height of ${h} cm. Find the volume of ice cream that fills the cone exactly, correct to 1 decimal place, in cm³.`, rd(PI * R * R * h / 3, 1), `$V = \\dfrac{1}{3}\\pi(${R})^2(${h}) = ${rd(PI * R * R * h / 3, 2)}$ ≈ ${rd(PI * R * R * h / 3, 1)} cm³.`); },
    r => { const R = r.int(10, 25), h = r.int(30, 60); return B(`A conical tank has a radius of ${R} cm and a height of ${h} cm. How many litres of water can it hold, correct to 1 decimal place? (1 litre = 1000 cm³)`, rd(PI * R * R * h / 3000, 1), `$V = \\dfrac{1}{3}\\pi(${R})^2(${h}) = ${rd(PI * R * R * h / 3, 1)}$ cm³ = ${rd(PI * R * R * h / 3000, 1)} litres.`); },
    r => { const [a, b, c] = tri(r); return B(`A party hat is a cone with radius ${a} cm and slant height ${c} cm. Find the area of paper needed to make the curved surface, correct to the nearest whole number, in cm².`, Math.round(PI * a * c), `$\\pi(${a})(${c}) = ${rd(PI * a * c, 2)}$ ≈ ${Math.round(PI * a * c)} cm².`); },
    r => { const R = r.int(4, 8), h = r.int(9, 15); return B(`A sand pile is in the shape of a cone with base radius ${R} m and height ${h} m. Find the volume of sand, correct to the nearest whole number, in m³.`, Math.round(PI * R * R * h / 3), `$V = \\dfrac{1}{3}\\pi(${R})^2(${h}) = ${rd(PI * R * R * h / 3, 2)}$ ≈ ${Math.round(PI * R * R * h / 3)} m³.`); },
    r => { const [a, b, c] = tri(r); return B(`A funnel is a cone of radius ${a} cm and height ${b} cm. Find the slant height of the funnel in cm.`, c, `$l = \\sqrt{${a}^2 + ${b}^2} = ${c}$ cm.`); },
    r => { const R = r.int(2, 5), h = r.int(8, 14); return B(`A cone-shaped paper cup has a radius of ${R} cm and a height of ${h} cm. Find the volume of water it holds when full, correct to the nearest cm³.`, Math.round(PI * R * R * h / 3), `$V = \\dfrac{1}{3}\\pi(${R})^2(${h}) = ${rd(PI * R * R * h / 3, 2)}$ ≈ ${Math.round(PI * R * R * h / 3)} cm³.`); }
  ]});

  /* ---- Spheres and hemispheres ---- */
  g.push({id: 'G3.2.volume-and-surface-area-of-pyramids-cones-and-spheres.3', plain: [
    r => { const R = r.int(2, 12); return B(`Find the volume of a sphere of radius ${R} cm, correct to 1 decimal place, in cm³.`, rd(4 / 3 * PI * R ** 3, 1), `$V = \\dfrac{4}{3}\\pi(${R})^3 = ${rd(4 / 3 * PI * R ** 3, 2)}$ ≈ ${rd(4 / 3 * PI * R ** 3, 1)} cm³.`); },
    r => { const R = r.int(2, 12); return B(`Find the surface area of a sphere of radius ${R} cm, correct to 1 decimal place, in cm².`, rd(4 * PI * R * R, 1), `$A = 4\\pi(${R})^2 = ${rd(4 * PI * R * R, 2)}$ ≈ ${rd(4 * PI * R * R, 1)} cm².`); },
    r => { const R = r.int(2, 10); return B(`A sphere has diameter ${2 * R} cm. Find its volume correct to the nearest whole number, in cm³.`, Math.round(4 / 3 * PI * R ** 3), `Radius = ${R}. $V = \\dfrac{4}{3}\\pi(${R})^3 = ${rd(4 / 3 * PI * R ** 3, 2)}$ ≈ ${Math.round(4 / 3 * PI * R ** 3)} cm³.`); },
    r => { const R = r.int(2, 12); return B(`Find the volume of a hemisphere of radius ${R} cm, correct to 1 decimal place, in cm³.`, rd(2 / 3 * PI * R ** 3, 1), `$V = \\dfrac{2}{3}\\pi(${R})^3 = ${rd(2 / 3 * PI * R ** 3, 2)}$ ≈ ${rd(2 / 3 * PI * R ** 3, 1)} cm³.`); },
    r => { const R = r.int(2, 12); return B(`Find the curved surface area of a hemisphere of radius ${R} cm, correct to 1 decimal place, in cm².`, rd(2 * PI * R * R, 1), `$2\\pi(${R})^2 = ${rd(2 * PI * R * R, 2)}$ ≈ ${rd(2 * PI * R * R, 1)} cm².`); },
    r => { const R = r.int(2, 12); return B(`Find the total surface area of a solid hemisphere of radius ${R} cm, correct to 1 decimal place, in cm².`, rd(3 * PI * R * R, 1), `Curved surface + flat face = $2\\pi r^2 + \\pi r^2 = 3\\pi(${R})^2 = ${rd(3 * PI * R * R, 2)}$ ≈ ${rd(3 * PI * R * R, 1)} cm².`); },
    r => { const R = r.int(2, 9); const V = 4 / 3 * PI * R ** 3; return B(`A sphere has volume ${rd(V, 1)} cm³. Find its radius correct to the nearest whole number, in cm.`, R, `$r^3 = \\dfrac{3V}{4\\pi} \\approx ${R ** 3}$, so $r = ${R}$ cm.`); },
    r => { const R = r.int(3, 9), k = r.pick([2, 3]); return B(`The radius of a sphere is multiplied by ${k}. By what factor is its surface area multiplied?`, k * k, `Surface area depends on $r^2$, so it is multiplied by ${k * k}.`); },
    r => { const R = r.int(3, 9), k = r.pick([2, 3]); return B(`The radius of a sphere is multiplied by ${k}. By what factor is its volume multiplied?`, k ** 3, `Volume depends on $r^3$, so it is multiplied by ${k ** 3}.`); },
    r => { const R = r.int(2, 9); return B(`A sphere has surface area ${4 * R * R}$\\pi$ cm². Find its radius in cm.`, R, `$4\\pi r^2 = ${4 * R * R}\\pi$, so $r^2 = ${R * R}$ and $r = ${R}$ cm.`); },
    r => { const R = r.int(3, 9), h = r.int(4, 10); return B(`A solid is made of a hemisphere of radius ${R} cm on top of a cylinder of radius ${R} cm and height ${h} cm. Find its volume correct to the nearest whole number, in cm³.`, Math.round(PI * R * R * h + 2 / 3 * PI * R ** 3), `Cylinder = $\\pi(${R})^2(${h})$, hemisphere = $\\dfrac{2}{3}\\pi(${R})^3$. Total = ${rd(PI * R * R * h + 2 / 3 * PI * R ** 3, 2)} ≈ ${Math.round(PI * R * R * h + 2 / 3 * PI * R ** 3)} cm³.`); },
    r => { const R = r.int(3, 9); return B(`A solid sphere of radius ${R} cm is cut in half to form two identical hemispheres. Find the total surface area of ONE hemisphere in terms of $\\pi$: give the coefficient of $\\pi$.`, 3 * R * R, `$3\\pi r^2 = ${3 * R * R}\\pi$ cm².`); },
    r => { const R = r.int(2, 6), r2 = r.int(1, 2); return B(`Find the volume of a hemisphere of radius ${R * 3} cm in terms of $\\pi$: give the coefficient of $\\pi$.`, 2 * (R * 3) ** 3 / 3, `$\\dfrac{2}{3}\\pi(${R * 3})^3 = ${2 * (R * 3) ** 3 / 3}\\pi$ cm³.`); },
    r => { const R = r.int(3, 9); return B(`Find the circumference of a great circle of a sphere with radius ${R} cm, correct to 1 decimal place, in cm.`, rd(2 * PI * R, 1), `$2\\pi(${R}) = ${rd(2 * PI * R, 2)}$ ≈ ${rd(2 * PI * R, 1)} cm.`); },
r => { const R = r.int(1, 4) * 3; return B(`The volume of a sphere of radius ${R} cm is ${4 * R ** 3 / 3}$\\pi$ cm³. Find the surface area of the sphere in terms of $\\pi$: give the coefficient of $\\pi$.`, 4 * R * R, `$4\\pi r^2 = ${4 * R * R}\\pi$ cm².`); },
    r => { const R = r.int(2, 10); return B(`A sphere has surface area ${rd(4 * PI * R * R, 1)} cm². Find its radius correct to the nearest whole number, in cm.`, R, `$r^2 = \\dfrac{A}{4\\pi} \\approx ${R * R}$, so $r = ${R}$ cm.`); },
r => { const R = r.int(1, 3) * 3; return B(`Find the volume of a sphere with diameter ${2 * R} cm in terms of $\\pi$: give the coefficient of $\\pi$.`, 4 * R ** 3 / 3, `$\\dfrac{4}{3}\\pi(${R})^3 = ${4 * R ** 3 / 3}\\pi$ cm³.`); }
  ], word: [
    r => { const R = r.int(3, 12); return B(`A football has a radius of ${R} cm. Find the volume of air it holds, correct to the nearest whole number, in cm³.`, Math.round(4 / 3 * PI * R ** 3), `$V = \\dfrac{4}{3}\\pi(${R})^3 = ${rd(4 / 3 * PI * R ** 3, 2)}$ ≈ ${Math.round(4 / 3 * PI * R ** 3)} cm³.`); },
    r => { const R = r.int(5, 15); return B(`A metal ball has a radius of ${R} cm. It is painted all over. Find the area to be painted, correct to the nearest whole number, in cm².`, Math.round(4 * PI * R * R), `$A = 4\\pi(${R})^2 = ${rd(4 * PI * R * R, 2)}$ ≈ ${Math.round(4 * PI * R * R)} cm².`); },
    r => { const R = r.int(10, 20); return B(`A bowl is a hemisphere with an inner radius of ${R} cm. How many litres of water can it hold, correct to 1 decimal place? (1 litre = 1000 cm³)`, rd(2 / 3 * PI * R ** 3 / 1000, 1), `$V = \\dfrac{2}{3}\\pi(${R})^3 = ${rd(2 / 3 * PI * R ** 3, 1)}$ cm³ = ${rd(2 / 3 * PI * R ** 3 / 1000, 1)} litres.`); },
    r => { const R = r.int(2, 5), n = r.int(2, 5); return B(`${n} ball bearings, each of radius ${R} mm, are melted and recast into one large sphere. Find the radius of the large sphere in mm, correct to 1 decimal place.`, rd(R * Math.cbrt(n), 1), `Total volume = ${n} × $\\dfrac{4}{3}\\pi(${R})^3$, so $R^3 = ${n} \\times ${R ** 3}$ and $R = ${rd(R * Math.cbrt(n), 2)}$ ≈ ${rd(R * Math.cbrt(n), 1)} mm.`); },
    r => { const R = r.int(3, 8), h = r.int(4, 9); return B(`A capsule is a cylinder of radius ${R} mm and length ${h} mm with a hemisphere at each end. Find the total volume correct to the nearest whole number, in mm³.`, Math.round(PI * R * R * h + 4 / 3 * PI * R ** 3), `Cylinder + two hemispheres = $\\pi(${R})^2(${h}) + \\dfrac{4}{3}\\pi(${R})^3 = ${rd(PI * R * R * h + 4 / 3 * PI * R ** 3, 2)}$ ≈ ${Math.round(PI * R * R * h + 4 / 3 * PI * R ** 3)} mm³.`); },
    r => { const R = r.int(6, 14); return B(`A solid hemispherical dome has a radius of ${R} m. Find the area of its curved surface to be painted, correct to the nearest whole number, in m².`, Math.round(2 * PI * R * R), `$2\\pi(${R})^2 = ${rd(2 * PI * R * R, 2)}$ ≈ ${Math.round(2 * PI * R * R)} m².`); }
  ]});

  /* ---- Statistical diagrams ---- */
  const dataList = (r, n, lo, hi) => Array.from({length: n}, () => r.int(lo, hi));
  g.push({id: 'G3.2.statistical-diagrams.1', plain: [
    r => { const f = [r.int(2, 8), r.int(3, 10), r.int(4, 12), r.int(2, 7)], t = f.reduce((a, b) => a + b, 0); return B(`A histogram has classes 0–10, 10–20, 20–30 and 30–40 with frequencies ${f.join(', ')}. Find the total frequency.`, t, `${f.join(' + ')} = ${t}.`); },
    r => { const f = [r.int(2, 8), r.int(3, 10), r.int(4, 12), r.int(2, 7)]; return B(`A histogram has classes 0–10, 10–20, 20–30 and 30–40 with frequencies ${f.join(', ')}. How many values are less than 20?`, f[0] + f[1], `${f[0]} + ${f[1]} = ${f[0] + f[1]}.`); },
    r => { const f = [r.int(2, 8), r.int(3, 10), r.int(4, 12), r.int(2, 7)], i = f.indexOf(Math.max(...f)); if (f.filter(v => v === Math.max(...f)).length > 1) return null; return B(`A histogram has classes 0–10, 10–20, 20–30 and 30–40 with frequencies ${f.join(', ')}. Find the lower limit of the modal class.`, i * 10, `The highest frequency is ${f[i]}, in the class ${i * 10}–${i * 10 + 10}.`); },
    r => { const f = [5, 10, 20, 15].map(v => v * r.int(1, 3)), t = f.reduce((a, b) => a + b, 0); return B(`A histogram has classes 0–10, 10–20, 20–30 and 30–40 with frequencies ${f.join(', ')}. What percentage of the values are in the class 20–30?`, rd(f[2] / t * 100, 1), `${f[2]}/${t} × 100 = ${rd(f[2] / t * 100, 1)}%.`); },
    r => { const a = r.int(2, 6), b = r.int(3, 8), c = r.int(2, 7); return B(`A dot diagram shows ${a} dots at 3, ${b} dots at 4 and ${c} dots at 5. How many data values are there altogether?`, a + b + c, `${a} + ${b} + ${c} = ${a + b + c}.`); },
    r => { const a = r.int(2, 6), b = r.int(3, 8), c = r.int(2, 7); return B(`A dot diagram shows ${a} dots at 3, ${b} dots at 4 and ${c} dots at 5. Find the sum of all the data values.`, 3 * a + 4 * b + 5 * c, `3 × ${a} + 4 × ${b} + 5 × ${c} = ${3 * a + 4 * b + 5 * c}.`); },
    r => { const a = r.int(2, 6), b = r.int(7, 10), c = r.int(2, 6); return B(`A dot diagram shows ${a} dots at 2, ${b} dots at 3 and ${c} dots at 4. Find the mode.`, 3, `The value 3 has the most dots (${b}).`); },
    r => { const d = dataList(r, 7, 10, 59).sort((x, y) => x - y); return B(`A stem-and-leaf diagram shows the data ${d.join(', ')}. Find the median.`, d[3], `The 4th of the 7 ordered values is ${d[3]}.`); },
    r => { const d = dataList(r, 8, 10, 59).sort((x, y) => x - y); return B(`A stem-and-leaf diagram represents the data ${d.join(', ')}. Find the range.`, d[7] - d[0], `Range = ${d[7]} − ${d[0]} = ${d[7] - d[0]}.`); },
    r => { const s = r.int(1, 4), l = [r.int(0, 3), r.int(3, 6), r.int(6, 9)]; return B(`In a stem-and-leaf diagram (key: 2 | 5 means 25), the stem ${s} has leaves ${l.join(', ')}. Find the largest value on this stem.`, s * 10 + l[2], `The largest leaf is ${l[2]}, so the value is ${s * 10 + l[2]}.`); },
    r => { const n = r.int(8, 20); return B(`A pie chart shows ${n} out of 40 students walk to school. What angle represents walking, in degrees?`, n * 9, `${n}/40 × 360 = ${n * 9}°.`); },
    r => { const f = [6, 8, 10, 4, 2].map(v => v + r.int(0, 3)), t = f.reduce((a, b) => a + b, 0); return B(`A frequency table shows frequencies ${f.join(', ')} for the scores 1, 2, 3, 4, 5. How many students scored more than 3?`, f[3] + f[4], `${f[3]} + ${f[4]} = ${f[3] + f[4]}.`); },
    r => { const f = [3, 7, 9, 5, 2].map(v => v + r.int(0, 2)), t = f.reduce((a, b) => a + b, 0); return B(`A frequency table shows frequencies ${f.join(', ')} for the scores 1, 2, 3, 4, 5. Find the total number of students.`, t, `${f.join(' + ')} = ${t}.`); },
    r => { const lo = r.int(1, 4) * 10, w = r.pick([5, 10]); return B(`A histogram has a class 20–${20 + w}. Find the class width.`, w, `${20 + w} − 20 = ${w}.`); },
r => { const a = r.int(5, 15), b = r.int(3, 12); return B(`A bar chart shows ${a} students chose Football and ${a + b} chose Basketball. How many more chose Basketball than Football?`, b, `${a + b} − ${a} = ${b}.`); }
  ], word: [
    r => { const d = dataList(r, 9, 40, 99).sort((x, y) => x - y); return B(`The marks of 9 students are shown in a stem-and-leaf diagram: ${d.join(', ')}. Find the median mark.`, d[4], `The 5th ordered mark is ${d[4]}.`); },
    r => { const f = [r.int(3, 9), r.int(5, 12), r.int(6, 14), r.int(2, 8)], t = f.reduce((a, b) => a + b, 0); return B(`A histogram shows the heights of ${t} plants in classes 0–10, 10–20, 20–30 and 30–40 cm with frequencies ${f.join(', ')}. How many plants are at least 20 cm tall?`, f[2] + f[3], `${f[2]} + ${f[3]} = ${f[2] + f[3]}.`); },
    r => { const a = r.int(5, 12), b = r.int(8, 15), c = r.int(10, 18), d = r.int(4, 10); return B(`A dot diagram shows the number of goals scored in matches: 0 goals in ${a} matches, 1 goal in ${b} matches, 2 goals in ${c} matches and 3 goals in ${d} matches. In how many matches were exactly 2 or more goals scored?`, c + d, `${c} + ${d} = ${c + d}.`); },
    r => { const a = r.int(2, 6), b = r.int(3, 8), c = r.int(4, 9), t = 2 * a + 3 * b + 4 * c, n = a + b + c; return B(`In a survey, ${a} students have 2 pets, ${b} students have 3 pets and ${c} students have 4 pets. How many pets do these students have altogether?`, t, `2 × ${a} + 3 × ${b} + 4 × ${c} = ${t}.`); },
    r => { const n = r.pick([20, 25, 40, 50]), p = r.pick([10, 20, 30, 40]); return B(`In a pie chart of ${n} students' favourite fruits, apples are shown by a sector of ${p * 3.6}°. How many students chose apples?`, n * p / 100, `${p * 3.6}/360 × ${n} = ${n * p / 100}.`); },
    r => { const d = dataList(r, 8, 20, 60); return B(`The ages of 8 club members are ${d.join(', ')}. Find the range of their ages.`, Math.max(...d) - Math.min(...d), `${Math.max(...d)} − ${Math.min(...d)} = ${Math.max(...d) - Math.min(...d)}.`); }
  ]});

  /* ---- Measures of central tendency ---- */
  g.push({id: 'G3.2.measures-of-central-tendency.1', plain: [
    r => { const n = r.int(5, 8), base = r.int(10, 40); const d = Array.from({length: n}, () => base + r.int(0, 10)), s = d.reduce((a, b) => a + b, 0); if (s % n) return null; return B(`Find the mean of ${d.join(', ')}.`, s / n, `Sum = ${s}. Mean = ${s} ÷ ${n} = ${s / n}.`); },
    r => { const d = dataList(r, 7, 3, 40), s = [...d].sort((a, b) => a - b); return B(`Find the median of ${d.join(', ')}.`, s[3], `In order: ${s.join(', ')}. The median is ${s[3]}.`); },
    r => { const d = dataList(r, 6, 3, 40), s = [...d].sort((a, b) => a - b); return B(`Find the median of ${d.join(', ')}.`, (s[2] + s[3]) / 2, `In order: ${s.join(', ')}. The median is (${s[2]} + ${s[3]}) ÷ 2 = ${(s[2] + s[3]) / 2}.`); },
    r => { const m = r.int(3, 20), d = [m, m, m, r.int(21, 30), r.int(31, 40), r.int(41, 50), m + 1]; return B(`Find the mode of ${r.shuffle(d).join(', ')}.`, m, `${m} appears three times, more than any other value.`); },
    r => { const f = [r.int(3, 8), r.int(4, 10), r.int(5, 12), r.int(2, 6)], x = [1, 2, 3, 4], t = f.reduce((a, b) => a + b, 0), s = f.reduce((a, v, i) => a + v * x[i], 0); return B(`Scores 1, 2, 3, 4 occur with frequencies ${f.join(', ')}. Find the mean score correct to 2 decimal places.`, rd(s / t, 2), `Total = ${f.map((v, i) => v + '×' + x[i]).join(' + ')} = ${s}. Mean = ${s} ÷ ${t} = ${rd(s / t, 2)}.`); },
    r => { const f = [r.int(3, 8), r.int(4, 10), r.int(5, 12), r.int(2, 6)], x = [1, 2, 3, 4], t = f.reduce((a, b) => a + b, 0), sorted = []; f.forEach((v, i) => { for (let k = 0; k < v; k++) sorted.push(x[i]); }); const med = t % 2 ? sorted[(t - 1) / 2] : (sorted[t / 2 - 1] + sorted[t / 2]) / 2; return B(`Scores 1, 2, 3, 4 occur with frequencies ${f.join(', ')}. Find the median score.`, med, `There are ${t} scores. The middle value${t % 2 ? ' is' : 's give'} ${med}.`); },
    r => { const f = [r.int(3, 8), r.int(4, 10), r.int(5, 12), r.int(2, 6)]; const x = [1, 2, 3, 4], i = f.indexOf(Math.max(...f)); if (f.filter(v => v === Math.max(...f)).length > 1) return null; return B(`Scores 1, 2, 3, 4 occur with frequencies ${f.join(', ')}. Find the mode.`, x[i], `The highest frequency is ${f[i]}, for the score ${x[i]}.`); },
    r => { const n = r.int(4, 9), m = r.int(10, 40); return B(`The mean of ${n} numbers is ${m}. Find their sum.`, n * m, `${n} × ${m} = ${n * m}.`); },
    r => { const a = r.int(5, 20), b = r.int(5, 20), c = r.int(5, 20), m = r.int(10, 18); const x = 4 * m - a - b - c; if (x <= 0) return null; return B(`The mean of four numbers is ${m}. Three of them are ${a}, ${b} and ${c}. Find the fourth number.`, x, `Total = ${4 * m}. Fourth = ${4 * m} − ${a + b + c} = ${x}.`); },
    r => { const n1 = r.int(5, 10), m1 = r.int(10, 30), n2 = r.int(5, 10), m2 = r.int(10, 30), t = n1 * m1 + n2 * m2; if (t % (n1 + n2)) return null; return B(`${n1} numbers have a mean of ${m1} and ${n2} other numbers have a mean of ${m2}. Find the mean of all ${n1 + n2} numbers.`, t / (n1 + n2), `Total = ${n1 * m1} + ${n2 * m2} = ${t}. Mean = ${t} ÷ ${n1 + n2} = ${t / (n1 + n2)}.`); },
    r => { const d = dataList(r, 5, 5, 30), m = d.reduce((a, b) => a + b, 0) / 5, x = r.int(5, 30); const s = [...d, x]; const mean = s.reduce((a, b) => a + b, 0) / 6; return B(`Find the mean of ${s.join(', ')}, correct to 1 decimal place.`, rd(mean, 1), `Sum = ${s.reduce((a, b) => a + b, 0)}. Mean = ${s.reduce((a, b) => a + b, 0)} ÷ 6 = ${rd(mean, 1)}.`); },
    r => { const lo = [0, 10, 20, 30], f = [r.int(3, 8), r.int(4, 10), r.int(5, 12), r.int(2, 6)]; const t = f.reduce((a, b) => a + b, 0), s = f.reduce((a, v, i) => a + v * (lo[i] + 5), 0); return B(`A grouped frequency table has classes 0–10, 10–20, 20–30 and 30–40 with frequencies ${f.join(', ')}. Using class mid-points, estimate the mean correct to 1 decimal place.`, rd(s / t, 1), `Mid-points 5, 15, 25, 35. Total = ${s}. Mean ≈ ${s} ÷ ${t} = ${rd(s / t, 1)}.`); },
    r => { const d = [r.int(5, 10), r.int(11, 20), r.int(21, 30), r.int(31, 40), r.int(41, 50)], k = r.int(2, 5); return B(`The median of five numbers is ${d[2]}. Each number is increased by ${k}. Find the new median.`, d[2] + k, `Adding ${k} to every value adds ${k} to the median: ${d[2] + k}.`); },
    r => { const m = r.int(10, 30), k = r.pick([2, 3]); return B(`The mean of a set of numbers is ${m}. Each number is multiplied by ${k}. Find the new mean.`, m * k, `The mean is also multiplied by ${k}: ${m * k}.`); }
  ], word: [
    r => { const d = dataList(r, 6, 50, 95), s = d.reduce((a, b) => a + b, 0); return B(`A student's marks in six tests are ${d.join(', ')}. Find the mean mark correct to 1 decimal place.`, rd(s / 6, 1), `Sum = ${s}. Mean = ${s} ÷ 6 = ${rd(s / 6, 1)}.`); },
    r => { const n = r.int(20, 30), m = r.int(150, 170), x = r.int(150, 180); const t = n * m + x; return B(`The mean height of ${n} students is ${m} cm. A new student of height ${x} cm joins the group. Find the new mean height, correct to 1 decimal place, in cm.`, rd(t / (n + 1), 1), `Total = ${n} × ${m} + ${x} = ${t}. New mean = ${t} ÷ ${n + 1} = ${rd(t / (n + 1), 1)} cm.`); },
    r => { const d = dataList(r, 7, 1, 9), s = [...d].sort((a, b) => a - b); return B(`The numbers of siblings of 7 students are ${d.join(', ')}. Find the median number of siblings.`, s[3], `In order: ${s.join(', ')}. The median is ${s[3]}.`); },
    r => { const a = r.int(60, 80), b = r.int(70, 90); const n1 = r.int(10, 20), n2 = r.int(10, 20), t = n1 * a + n2 * b; if (t % (n1 + n2)) return null; return B(`Class A of ${n1} students has a mean mark of ${a}. Class B of ${n2} students has a mean mark of ${b}. Find the mean mark of all ${n1 + n2} students.`, t / (n1 + n2), `Total = ${n1 * a} + ${n2 * b} = ${t}. Mean = ${t} ÷ ${n1 + n2} = ${t / (n1 + n2)}.`); },
    r => { const s = r.int(60, 75), t = r.int(3, 5), target = s + r.int(2, 6); const need = target * (t + 1) - s * t; return B(`Mei's mean mark in ${t} tests is ${s}. What mark does she need in the next test so that her mean for all ${t + 1} tests is ${target}?`, need, `Total needed = ${target} × ${t + 1} = ${target * (t + 1)}. Current total = ${s * t}. She needs ${need}.`); },
    r => { const d = dataList(r, 5, 12, 40); const m = d.reduce((a, b) => a + b, 0) / 5; const k = r.int(2, 8); const s = d.reduce((a, b) => a + b, 0); return B(`The ages of five cousins are ${d.join(', ')}. Find their mean age after ${k} years, correct to 1 decimal place.`, rd(s / 5 + k, 1), `Mean now = ${rd(s / 5, 2)}. After ${k} years the mean is ${rd(s / 5, 2)} + ${k} = ${rd(s / 5 + k, 1)}.`); }
  ]});

  /* ---- Probability ---- */
  g.push({id: 'G3.2.probability.1', plain: [
    r => { const t = r.pick([20, 25, 40, 50]), a = r.int(2, t - 2); return B(`A bag has ${t} balls and ${a} are red. One ball is chosen at random. Find the probability that it is red, as a decimal.`, rd(a / t, 4), `P(red) = ${a}/${t} = ${rd(a / t, 4)}.`); },
    r => { const t = r.pick([20, 25, 40, 50]), a = r.int(2, t - 2); return B(`A bag has ${t} balls and ${a} are red. One ball is chosen at random. Find the probability that it is NOT red, as a decimal.`, rd(1 - a / t, 4), `P(not red) = 1 − ${a}/${t} = ${rd(1 - a / t, 4)}.`); },
r => { const n = r.int(2, 4); return B(`A fair coin is tossed ${n} times. Find the probability that all ${n} tosses show heads, as a decimal.`, rd(1 / 2 ** n, 4), `P(all heads) = (1/2)^${n} = ${rd(1 / 2 ** n, 4)}.`); },
    r => { const n = r.pick([20, 40, 50, 100]), p = r.pick([0.1, 0.2, 0.25, 0.4]); return B(`The probability that a bulb is faulty is ${p}. In a box of ${n} bulbs, how many are expected to be faulty?`, n * p, `${n} × ${p} = ${n * p}.`); },
    r => { const a = r.int(1, 4) * 5, b = r.int(2, 5) * 5, c = 100 - a - b; if (c <= 0) return null; return B(`In a bag, the probability of picking a red ball is ${a / 100} and a blue ball is ${b / 100}. All other balls are green. Find the probability of picking a green ball, as a decimal.`, rd(c / 100, 2), `P(green) = 1 − ${a / 100} − ${b / 100} = ${rd(c / 100, 2)}.`); },
    r => { const a = r.int(2, 6), b = r.int(2, 6); return B(`A coin is tossed and a die is rolled. How many possible outcomes are there?`, 12, `2 × 6 = 12.`); },
    r => { const a = r.int(2, 4), b = r.int(2, 4); return B(`A spinner has ${a + 2} equal sectors and a coin is tossed. How many outcomes are in the sample space?`, 2 * (a + 2), `${a + 2} × 2 = ${2 * (a + 2)}.`); },
    r => { const n = r.int(2, 6) * 10, p = r.pick([0.2, 0.3, 0.5]); return B(`The probability of rain on a day is ${p}. How many rainy days are expected in ${n} days?`, n * p, `${n} × ${p} = ${n * p}.`); },
    r => { const a = r.int(3, 9), b = r.int(2, 8), t = a + b; return B(`A box has ${a} red and ${b} blue pens. How many pens must be added (all green) so that the probability of picking a red pen is exactly $\\dfrac{${a}}{${a * 2 + b}}$?`, a, `The total must be ${a * 2 + b}. So ${a * 2 + b} − ${t} = ${a} green pens are added.`); },
    r => { const t = r.pick([4, 5, 8, 10, 20]), a = r.int(1, t - 1); return B(`The probability of an event is $\\dfrac{${a}}{${t}}$. Write the probability of the event NOT happening as a decimal.`, rd(1 - a / t, 4), `1 − ${a}/${t} = ${rd(1 - a / t, 4)}.`); },
    r => { const a = r.pick([2, 3, 4, 5]), t = a * 10; return B(`The probability of winning a game is ${a / 10}. Find the probability of losing as a decimal (no draws).`, rd(1 - a / 10, 1), `1 − ${a / 10} = ${rd(1 - a / 10, 1)}.`); },
    r => { const t = r.pick([20, 40, 50]), a = r.int(3, 9), b = r.int(3, 9); return B(`Of ${t} students, ${a} play football only, ${b} play basketball only and the rest play neither. Find the probability that a randomly chosen student plays neither, as a decimal.`, rd((t - a - b) / t, 4), `(${t} − ${a} − ${b})/${t} = ${(t - a - b)}/${t} = ${rd((t - a - b) / t, 4)}.`); },
    r => { const t = r.pick([20, 25, 40, 50]), a = r.int(2, 9), b = r.int(2, 9); return B(`A box has ${t} cards. ${a} are marked A, ${b} are marked B and the rest are blank. A card is drawn at random. Find the probability that it is marked A or B, as a decimal.`, rd((a + b) / t, 4), `P(A or B) = (${a} + ${b})/${t} = ${rd((a + b) / t, 4)}.`); },
    r => { const n = r.pick([2, 3, 4]); return B(`${n} fair coins are tossed. How many outcomes are in the sample space?`, 2 ** n, `Each coin has 2 outcomes: 2^${n} = ${2 ** n}.`); }
  ], word: [
    r => { const g1 = r.int(2, 6), b = r.int(3, 9), t = 10 + r.int(0, 2) * 5; return B(`A class has ${t} students, of whom ${g1 + b} are girls. A student is chosen at random. Find the probability that the student is a boy, as a decimal.`, rd((t - g1 - b) / t, 4), `Boys = ${t} − ${g1 + b} = ${t - g1 - b}. P(boy) = ${t - g1 - b}/${t} = ${rd((t - g1 - b) / t, 4)}.`); },
    r => { const n = r.pick([50, 100, 200]), p = r.pick([0.05, 0.1, 0.2]); return B(`The probability that a sweet in a jar is red is ${p}. The jar contains ${n} sweets. How many red sweets are expected?`, n * p, `${n} × ${p} = ${n * p}.`); },
    r => { const a = r.int(3, 8), b = r.int(2, 6), c = r.int(3, 9), t = a + b + c; if (![20, 25, 40, 50, 100, 10, 8, 4, 5, 2].includes(t)) return null; return B(`A bag contains ${a} red, ${b} blue and ${c} yellow marbles. A marble is picked at random. Find the probability that it is yellow, as a decimal.`, rd(c / t, 4), `P(yellow) = ${c}/${t} = ${rd(c / t, 4)}.`); },
    r => { const n = r.int(2, 6) * 20, p = r.pick([0.25, 0.4, 0.5]); return B(`In a survey of ${n} people, the probability that a person owns a bicycle is ${p}. How many of the ${n} people are expected to own a bicycle?`, n * p, `${n} × ${p} = ${n * p}.`); },
    r => { const a = r.int(2, 5), t = r.pick([20, 25, 40, 50]); return B(`A raffle sells ${t} tickets and Ali buys ${a} of them. Find the probability that Ali wins the prize, as a decimal.`, rd(a / t, 4), `P(win) = ${a}/${t} = ${rd(a / t, 4)}.`); },
    r => { const a = r.int(3, 8), t = r.pick([10, 20, 25, 40, 50]); return B(`In a factory, ${a} out of every ${t} items are defective. An item is picked at random. Find the probability that it is not defective, as a decimal.`, rd(1 - a / t, 4), `P(not defective) = 1 − ${a}/${t} = ${rd(1 - a / t, 4)}.`); }
  ]});

  return g;
};
